import { 
  MeshBasicNodeMaterial 
} from 'three/webgpu';
import { 
  uv, 
  vec3, 
  mix, 
  texture, 
  uniform 
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root container
  const root = new Group();

  // Color Definitions from Visual Spec
  const colorInk = new Color('#16161d');
  const colorPaper = new Color('#e8ecf2');
  const colorAccent = new Color('#ff2a38');
  const colorSurface = new Color('#0b0b10');

  // Elements Array for Tracking Disposables
  const disposables = [];
  const activeTimelines = [];

  // --- 1. Backdrop Plane (W-PCP §9 STAGE REQUIREMENT) ---
  const bgGeom = new PlaneGeometry(7.5, 6.5);
  disposables.push(bgGeom);

  // Gradient Material for Backdrop using TSL
  const bgMat = new MeshBasicNodeMaterial();
  const topColor = vec3(colorInk.r, colorInk.g, colorInk.b);
  const bottomColor = vec3(colorSurface.r, colorSurface.g, colorSurface.b);

  // Vertical gradient Node using UV coordinate
  bgMat.colorNode = mix(bottomColor, topColor, uv().y);

  const backdrop = new Mesh(bgGeom, bgMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // --- 2. Main Machined Bezel & Card (Aspect Ratio 1.6) ---
  const cardWidth = 4.0;
  const cardHeight = 2.5;

  // Bezel/Frame Mesh
  const bezelGeom = new PlaneGeometry(cardWidth + 0.06, cardHeight + 0.06);
  const bezelMat = new MeshBasicNodeMaterial({ color: colorPaper });
  const bezel = new Mesh(bezelGeom, bezelMat);
  bezel.position.set(0, 0, -0.01);
  root.add(bezel);
  disposables.push(bezelGeom, bezelMat);

  // Fine Accent Pin-stripe
  const accentStripGeom = new PlaneGeometry(cardWidth + 0.1, 0.02);
  const accentStripMat = new MeshBasicNodeMaterial({ color: colorAccent });
  const accentStrip = new Mesh(accentStripGeom, accentStripMat);
  accentStrip.position.set(0, -cardHeight / 2 - 0.06, 0);
  root.add(accentStrip);
  disposables.push(accentStripGeom, accentStripMat);

  // Sprite / Textured Surface Plate
  const spriteGeom = new PlaneGeometry(cardWidth, cardHeight);
  disposables.push(spriteGeom);

  const spriteMat = new MeshBasicNodeMaterial();
  // Safe texture fallback + texture loading
  const imgUrl = config.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png';

  ctx.textureLoader.loadTexture(imgUrl).then((tex) => {
    tex.colorSpace = ctx.THREE.SRGBColorSpace;

    // Atlas Source Rect Mapping: 0, 0, 512, 320 on a standard 512x512 texture
    // Adjust texture coordinate transformation node using TSL
    const atlasUV = uv().mul(vec3(1.0, 320 / 512, 1.0));
    spriteMat.colorNode = texture(tex, atlasUV);
    spriteMat.needsUpdate = true;
  }).catch((err) => {
    // Graceful fallback to dark engineered surface with accent gradient
    spriteMat.colorNode = mix(
      vec3(colorSurface.r, colorSurface.g, colorSurface.b),
      vec3(colorInk.r, colorInk.g, colorInk.b),
      uv().x
    );
    spriteMat.needsUpdate = true;
  });

  const cardSprite = new Mesh(spriteGeom, spriteMat);
  root.add(cardSprite);
  disposables.push(spriteMat);

  // --- 3. Billboarding Behavior (Render Mode Prompt) ---
  const targetRotation = { x: 0, y: 0 };

  const onBeforeRender = () => {
    // Gentle floating billboard behavior - slightly orienting to standard view vectors
    cardSprite.rotation.y = targetRotation.y;
    bezel.rotation.y = targetRotation.y;
  };

  // Assign internal tick loop listener if desired, or let engine handle static view
  // (We use a very subtle slow breathing motion to feel luxury class)
  const breathingTl = gsap.timeline({ repeat: -1, yoyo: true });
  breathingTl.to(root.position, {
    y: '-=0.04',
    duration: 3.5,
    ease: 'power1.inOut'
  });
  activeTimelines.push(breathingTl);

  // --- 4. Cleanup ---
  root.userData = {
    cleanup() {
      activeTimelines.forEach((tl) => tl.kill());
      disposables.forEach((d) => d.dispose());
    }
  };

  return root;
}
